// ═══════════════════════════════════════════════════════════════════════════
// Dashboard de Pulso — TSQMI por Repositório (Estilo "Cards" Arredondados)
// ═══════════════════════════════════════════════════════════════════════════

try {
  const panelData = context.panel.data;
  if (!panelData || !panelData.series || panelData.series.length === 0) {
    return { title: { text: 'Sem dados disponíveis', left: 'center', top: 'center' } };
  }

  function toArr(field) {
    if (!field) return [];
    const v = field.values;
    if (!v) return [];
    if (v.buffer) return Array.from(new Float64Array(v.buffer));
    if (Array.isArray(v)) return v;
    if (typeof v.toArray === 'function') return v.toArray();
    return Array.from(v);
  }

  const frame = panelData.series[0];
  if (!frame || frame.fields.length === 0) {
    return { title: { text: 'Query A sem retorno', left: 'center', top: 'center' } };
  }

  // ── 1. Extração de Dados Principais ─────────────────────────────────────────
  const names = toArr(frame.fields.find(f => f.name === 'name'));
  const rawDatetimes = toArr(frame.fields.find(f => f.name === 'datetime'));
  const tsqmis = toArr(frame.fields.find(f => f.name === 'tsqmi'));

  const datetimes = rawDatetimes.map(ts => {
    const d = new Date(Number(ts));
    if (isNaN(d.getTime())) return String(ts);
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return yyyy + '-' + mm + '-' + dd;
  });

  // ── 2. Extração de Releases ────────────────────────────────────────────────
  let releaseNames = [], releaseDates = [], releaseRepos = [];
  if (panelData.series.length > 1) {
    const relFrame = panelData.series[1];
    releaseNames = toArr(relFrame.fields.find(f => f.name === 'release_name'));
    releaseDates = toArr(relFrame.fields.find(f => f.name === 'release_date'));
    releaseRepos = toArr(relFrame.fields.find(f => f.name === 'repository_name'));
  }

  // ── 3. Agrupamento por Repositório ─────────────────────────────────────────
  const groupedData = {};
  for (let i = 0; i < names.length; i++) {
    const repoName = names[i];
    if (!groupedData[repoName]) {
      groupedData[repoName] = { datetimes: [], tsqmi: [] };
    }
    groupedData[repoName].datetimes.push(datetimes[i]);
    groupedData[repoName].tsqmi.push(tsqmis[i]);
  }

  const REPO_COLORS = ['#059669', '#2563EB', '#D97706', '#DC2626', '#7C3AED', '#0891B2', '#EA580C', '#BE123C', '#4F46E5'];

  const uniqueDatetimes = [...new Set(datetimes)].sort();
  const SPS = 60;
  const globalXAxisData = [];

  if (uniqueDatetimes.length > 0) {
    for (let i = 0; i < uniqueDatetimes.length - 1; i++) {
      globalXAxisData.push(uniqueDatetimes[i]);
      for (let s = 1; s < SPS; s++) globalXAxisData.push('');
    }
    globalXAxisData.push(uniqueDatetimes[uniqueDatetimes.length - 1]);
  }

  const repositories = Object.keys(groupedData).sort().map((name, idx) => {
    const repoColor = REPO_COLORS[idx % REPO_COLORS.length];

    const alignedTsqmi = uniqueDatetimes.map(dt => {
      const i = groupedData[name].datetimes.indexOf(dt);
      return i !== -1 ? groupedData[name].tsqmi[i] : null;
    });

    const validVals = alignedTsqmi.filter(v => v !== null && v !== undefined);
    const lastVal = validVals.length > 0 ? validVals[validVals.length - 1] : 0;
    const prevVal = validVals.length > 1 ? validVals[validVals.length - 2] : null;

    let labelStr = name;
    if (name.length > 22) labelStr = name.substring(0, 19) + '...';

    return { name, label: labelStr, color: repoColor, alignedTsqmi, lastVal, prevVal };
  });

  const nRepos = repositories.length;

  // ── 4. Motor Matemático do Pulso ───────────────────────────────────────────
  function msgPulseToLane(scores, laneIndex) {
    const pts = [];
    let lastV = 0;
    const cleanScores = scores.map(s => {
      if (s !== null && s !== undefined) lastV = s;
      return lastV;
    });

    for (let ii = 0; ii < cleanScores.length - 1; ii++) {
      const a = cleanScores[ii], b = cleanScores[ii + 1];
      const delta = b - a;
      const pk = delta * 6.5;

      for (let s = 0; s < SPS; s++) {
        const t = s / SPS;
        let v;
        if (t < 0.30) { v = a; }
        else if (t < 0.42) { const p = (t - 0.30) / 0.12; v = a + pk * Math.sin(p * Math.PI * 0.5); }
        else if (t < 0.56) { const p = (t - 0.42) / 0.14; v = a + pk * (1 - p); }
        else if (t < 0.68) { const p = (t - 0.56) / 0.12; v = b - delta * 0.50 * Math.sin(p * Math.PI); }
        else { v = b; }

        pts.push(laneIndex + 0.30 - (v * 0.65));
      }
    }
    if (cleanScores.length > 0) {
      pts.push(laneIndex + 0.30 - (cleanScores[cleanScores.length - 1] * 0.65));
    }
    return pts;
  }

  // ── 5. Configuração Temática e Rich Text ───────────────────────────────────
  const cardBgColorOven = '#F3F4F6';  
  const cardBgColorOdd = '#FAFAFA';   
  const cardBorderColor = '#4B5563';  // Cinza escuro para delimitação clara
  const titleColor = '#111827';
  const subColor = '#6B7280';

  const richObj = {
    varPos: { fontSize: 11, color: '#10B981', align: 'left', fontWeight: 'bold', padding: [4, 0, 0, 0] },
    varNeg: { fontSize: 11, color: '#EF4444', align: 'left', fontWeight: 'bold', padding: [4, 0, 0, 0] },
    varNeu: { fontSize: 11, color: subColor, align: 'left', fontWeight: 'bold', padding: [4, 0, 0, 0] },
    subTxt: { fontSize: 10, color: subColor, align: 'left', padding: [2, 0, 0, 0] }
  };

  repositories.forEach((r, i) => {
    richObj['repo' + i] = { fontSize: 16, fontWeight: 'bold', color: titleColor, align: 'left', padding: [0, 0, 6, 0] };
    richObj['val' + i] = { fontSize: 24, fontWeight: 'bold', color: r.color, align: 'left' };
  });

  const yAxisFormatter = (value) => {
    const idx = Math.round(value);
    if (value >= -0.1 && value < nRepos && Math.abs(value - idx) < 0.1) {
      const r = repositories[idx];
      if (!r) return '';

      let varText = '0.00%';
      let varStyle = 'varNeu';
      if (r.prevVal !== null) {
        const delta = r.lastVal - r.prevVal;
        if (r.prevVal !== 0) {
          const pct = (delta / r.prevVal) * 100;
          const arrow = pct > 0 ? '▲ ' : (pct < 0 ? '▼ ' : '');
          varText = arrow + Math.abs(pct).toFixed(2) + '%';
          varStyle = pct > 0 ? 'varPos' : (pct < 0 ? 'varNeg' : 'varNeu');
        } else if (r.lastVal > 0) {
          varText = '▲ 100.00%';
          varStyle = 'varPos';
        }
      }
      return '{repo' + idx + '|' + r.label + '}\n{val' + idx + '|' + r.lastVal.toFixed(3) + '}\n{' + varStyle + '|' + varText + '}\n{subTxt|último valor}';
    }
    return '';
  };

  // ── 6. Geração de Séries (Cards Customizados + Linhas MSG) ──────────────────

  // Série Customizada para renderizar os cartões com cantos arredondados nativos
  const backgroundSeries = {
    type: 'custom',
    renderItem: function (params, api) {
      const laneIndex = api.value(0);
      const yTop = api.coord([0, laneIndex - 0.42])[1];
      const yBottom = api.coord([0, laneIndex + 0.42])[1];
      const gridRect = params.coordSys;

      return {
        type: 'rect',
        shape: {
          x: gridRect.x,
          y: yTop,
          width: gridRect.width,
          height: yBottom - yTop,
          r: 8 // ARRENDONDAMENTO DEFINITIVO DOS CANTOS (8px)
        },
        style: {
          fill: laneIndex % 2 === 0 ? cardBgColorOven : cardBgColorOdd,
          stroke: cardBorderColor,
          lineWidth: 2 // Espessura da borda cinza escura
        },
        silent: true
      };
    },
    data: repositories.map((_, i) => [i]),
    yAxisIndex: 0,
    xAxisIndex: 0
  };

  const lineSeries = repositories.map((repo, repoIdx) => {
    const repoReleases = [];

    for (let i = 0; i < releaseNames.length; i++) {
      if (releaseRepos[i] === repo.name && releaseNames[i]) {
        let rDate = new Date(releaseDates[i]);
        if (isNaN(rDate.getTime())) rDate = new Date(Number(releaseDates[i]));
        const rTime = rDate.getTime();

        let closestIdx = 0, minDiff = Infinity;
        for (let j = 0; j < uniqueDatetimes.length; j++) {
          const diff = Math.abs(new Date(uniqueDatetimes[j]).getTime() - rTime);
          if (diff < minDiff) { minDiff = diff; closestIdx = j; }
        }

        if (minDiff < Infinity) {
          repoReleases.push({ name: releaseNames[i], dateIndex: closestIdx });
        }
      }
    }

    return {
      name: repo.label,
      type: 'line',
      smooth: false,
      symbol: 'none',
      lineStyle: { color: repo.color, width: 2.5 },
      data: msgPulseToLane(repo.alignedTsqmi, repoIdx),
      markLine: repoReleases.length > 0 ? {
        silent: true,
        symbol: ['none', 'none'],
        label: {
          position: 'end',
          align: 'center',
          distance: 4,
          formatter: '{b}',
          backgroundColor: '#FDE047', color: '#1F2937',
          padding: [3, 5], borderRadius: 3, fontSize: 10, fontWeight: 'bold'
        },
        lineStyle: { color: '#FACC15', type: 'dashed', width: 2 },
        data: repoReleases.map(r => {
          return [
            { coord: [r.dateIndex * SPS, repoIdx + 0.42] }, 
            { coord: [r.dateIndex * SPS, repoIdx - 0.42], name: r.name } 
          ];
        })
      } : undefined
    };
  });

  // Consolidação das séries (Background injetado no índice 0)
  const series = [backgroundSeries, ...lineSeries];

  // ── 7. Elementos Gráficos Periféricos ──────────────────────────────────────
  function exportCSV() {
    let csv = 'Repositório,Data,TSQMI\n';
    repositories.forEach(repo => {
      repo.alignedTsqmi.forEach((val, idx) => {
        if (val !== null && val !== undefined) {
          csv += repo.name + ',' + uniqueDatetimes[idx] + ',' + val.toFixed(4) + '\n';
        }
      });
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'tsqmi_export_' + new Date().toISOString().split('T')[0] + '.csv';
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  const titleGraphic = {
    type: 'group', left: 20, top: 0,
    children: [
      { type: 'text', left: 0, top: 0, style: { text: 'Gráfico MSG — Evolução de Qualidade', fontSize: 16, fontWeight: 'bold', fill: titleColor } },
      { type: 'text', left: 0, top: 20, style: { text: 'Uma linha por característica • pico = variação entre medições', fontSize: 11, fill: subColor } },
    ],
  };

  const validCount = repositories.reduce((acc, r) => acc + r.alignedTsqmi.filter(v => v !== null).length, 0);
  const globalLastDate = uniqueDatetimes.length > 0 ? uniqueDatetimes[uniqueDatetimes.length - 1] : 'N/A';
  const footerGraphic = {
    type: 'text', left: 'center', bottom: 0,
    style: { text: nRepos + ' repositórios • ' + validCount + ' medições totais · Última medição: ' + globalLastDate, fontSize: 11, fill: subColor },
  };

  const exportGroupGraphic = {
    type: 'group', right: 40, top: 0,
    children: [
      { type: 'text', left: -85, top: 7, style: { text: 'exportar .csv', fontSize: 12, fontWeight: 'bold', fill: subColor } },
      { type: 'rect', left: -90, top: 0, shape: { width: 120, height: 30 }, style: { fill: 'transparent' }, cursor: 'pointer', onclick: exportCSV, z: 100 }
    ]
  };

  const xStep = Math.max(1, Math.floor(uniqueDatetimes.length / 8));
  const maxVisibleRows = 4;
  const isScrollable = nRepos > maxVisibleRows;
  const zoomEnd = isScrollable ? (maxVisibleRows / nRepos) * 100 : 100;

  const iconPathSegment = 'path://M14 2H6C4.89 2 4 2.9 4 4V20C4 21.11 4.89 22 6 ' +
    '22H18C19.11 22 20 21.11 20 20V8L14 2M18 20H6V4H13V9H' +
    '18V20M12 19L8 15H10.5V12H13.5V15H16L12 19Z';

  // ── 8. Configuração de Retorno ECharts ─────────────────────────────────────
  return {
    backgroundColor: 'transparent',
    graphic: [titleGraphic, footerGraphic, exportGroupGraphic],
    toolbox: {
      show: true, right: 40, top: 0,
      feature: {
        myExportCsv: {
          show: true, title: 'Exportar CSV', icon: iconPathSegment, onclick: exportCSV
        }
      }
    },
    tooltip: {
      trigger: 'axis',
      axisPointer: { type: 'line' },
      formatter: params => {
        const measureIdx = Math.floor(params[0].dataIndex / SPS);
        if (measureIdx >= uniqueDatetimes.length) return '';
        let html = '<div style="color: #333; font-weight: bold; margin-bottom: 5px;">' + uniqueDatetimes[measureIdx] + '</div>';

        params.forEach(p => {
          if (p.seriesType === 'custom') return; // Ignora a série estrutural de fundo
          const repoIdx = p.seriesIndex - 1;    // Corrige o desvio do índice
          const repo = repositories[repoIdx];
          if (!repo) return;

          const v = repo.alignedTsqmi[measureIdx] ?? 0;
          const prev = measureIdx > 0 ? (repo.alignedTsqmi[measureIdx - 1] ?? null) : null;
          const delta = prev !== null ? v - prev : null;

          html += '<span style="color:' + repo.color + '">■</span> <b>' + repo.label + '</b>: ' + v.toFixed(4);
          if (delta !== null && delta !== 0) {
            const col = delta > 0 ? '#10B981' : '#EF4444';
            const sign = delta > 0 ? '+' : '';
            html += ' <span style="color:' + col + '; font-size: 11px;">(' + sign + delta.toFixed(4) + ')</span>';
          }
          html += '<br/>';
        });
        return html;
      }
    },
    grid: {
      top: 60,
      bottom: 40,
      left: 190,
      right: isScrollable ? 40 : 20,
      show: false
    },
    dataZoom: [
      {
        type: 'slider', yAxisIndex: 0, show: isScrollable, right: 10, width: 12, start: 0, end: zoomEnd,
        borderColor: 'transparent',
        backgroundColor: '#F3F4F6',
        fillerColor: '#D1D5DB',
        handleStyle: { color: '#9CA3AF' }
      },
      { type: 'inside', yAxisIndex: 0, disabled: !isScrollable }
    ],
    xAxis: {
      type: 'category', data: globalXAxisData,
      axisLabel: {
        color: subColor, fontSize: 10,
        interval: function (index, value) {
          if (value === '') return false;
          const origIdx = Math.floor(index / SPS);
          return origIdx % xStep === 0 || origIdx === uniqueDatetimes.length - 1 || origIdx === 0;
        },
        formatter: (value) => value ? String(value).slice(5, 10).replace('-', '/') : ''
      },
      axisTick: { show: false }, axisLine: { show: false }, splitLine: { show: false }
    },
    yAxis: {
      type: 'value',
      min: -1,
      max: nRepos,
      inverse: true,
      interval: 1,
      axisLabel: {
        formatter: yAxisFormatter,
        rich: richObj,
        margin: 180,
        align: 'left',
        verticalAlign: 'middle'
      },
      axisTick: { show: false }, axisLine: { show: false }, splitLine: { show: false }
    },
    series: series
  };
} catch (e) {
